use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let n = input["n"].as_u64().unwrap() as usize;
    let edges = input["edges"].as_array().unwrap();
    let mut indegree = vec![0; n];

    for edge in edges {
        let u = edge[0].as_u64().unwrap() as usize;
        let v = edge[1].as_u64().unwrap() as usize;
        indegree[v] += 1;
    }

    json!(indegree)
}
